func taskObj(id string, prio, rel, exec, dead int64) string {
	return `{"id":"` + id + `","priority":` + itoa(int(prio)) +
		`,"release":` + itoa(int(rel)) +
		`,"execution":` + itoa(int(exec)) +
		`,"deadline":` + itoa(int(dead)) + `}`
