63	func handleAnalyze(w http.ResponseWriter, r *http.Request) {
64		if r.Method != http.MethodPost {
65			w.Header().Set("Allow", http.MethodPost)
66			writeAnalyzeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
67			return
68		}
69		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
70		if err != nil || mediaType != "application/json" {
71			writeAnalyzeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type")
72			return
73		}
74		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxAnalyzeBodyBytes))
75		if err != nil {
76			writeAnalyzeError(w, http.StatusBadRequest, "invalid_json")
77			return
78		}
79		// Reject duplicate keys and trailing tokens before the strict struct decode.
80		if err := rejectDuplicateKeys(body); err != nil {
81			writeAnalyzeError(w, http.StatusBadRequest, "invalid_json")
82			return
83		}
84		dec := json.NewDecoder(bytes.NewReader(body))
85		dec.DisallowUnknownFields()
86		var req analyzeRequest
87		if err := dec.Decode(&req); err != nil {
88			// Well-formed JSON with a value of the wrong JSON type violates the
89			// request schema (422); malformed syntax and unknown fields stay 400.
90			var typeErr *json.UnmarshalTypeError
91			if errors.As(err, &typeErr) {
92				writeAnalyzeError(w, http.StatusUnprocessableEntity, "validation_failed")
93				return
94			}
95			writeAnalyzeError(w, http.StatusBadRequest, "invalid_json")
96			return
97		}
98		var extra json.RawMessage
99		if err := dec.Decode(&extra); err != io.EOF {
100			writeAnalyzeError(w, http.StatusBadRequest, "invalid_json")
101			return
102		}
103		tasks, ok := validateAnalyzeRequest(&req)
104		if !ok {
105			writeAnalyzeError(w, http.StatusUnprocessableEntity, "validation_failed")
106			return
107		}
108		resp := simulateSchedule(tasks, *req.Horizon)
109		w.Header().Set("Content-Type", "application/json; charset=utf-8")
110		w.WriteHeader(http.StatusOK)
111		_ = json.NewEncoder(w).Encode(resp)
112	}
