118	var errDuplicateKey = errors.New("duplicate JSON object key")
119	
120	// rejectDuplicateKeys tokenizes the whole JSON document and rejects repeated
121	// member names at any object nesting level or trailing content.
122	func rejectDuplicateKeys(data []byte) error {
123		dec := json.NewDecoder(bytes.NewReader(data))
124		dec.UseNumber()
125		if err := scanDuplicateKeys(dec); err != nil {
126			return err
127		}
128		if _, err := dec.Token(); err != io.EOF {
129			return fmt.Errorf("trailing content after JSON document")
130		}
131		return nil
132	}
133	
134	func scanDuplicateKeys(dec *json.Decoder) error {
135		t, err := dec.Token()
136		if err != nil {
137			return err
138		}
139		d, ok := t.(json.Delim)
140		if !ok {
141			return nil
142		}
143		switch d {
144		case '{':
145			seen := make(map[string]struct{})
146			for dec.More() {
147				keyTok, err := dec.Token()
148				if err != nil {
149					return err
150				}
151				key := keyTok.(string)
152				if _, dup := seen[key]; dup {
153					return errDuplicateKey
154				}
155				seen[key] = struct{}{}
156				if err := scanDuplicateKeys(dec); err != nil {
157					return err
158				}
159			}
160			if _, err := dec.Token(); err != nil {
161				return err
162			}
163		case '[':
164			for dec.More() {
165				if err := scanDuplicateKeys(dec); err != nil {
166					return err
167				}
168			}
169			if _, err := dec.Token(); err != nil {
170				return err
171			}
172		}
173		return nil
174	}
