176	func validateAnalyzeRequest(req *analyzeRequest) ([]scheduledTask, bool) {
177		if req.Horizon == nil || *req.Horizon <= 0 || *req.Horizon > maxHorizon {
178			return nil, false
179		}
180		if req.Tasks == nil || len(*req.Tasks) == 0 || len(*req.Tasks) > maxTasks {
181			return nil, false
182		}
183		horizon := *req.Horizon
184		tasks := make([]scheduledTask, 0, len(*req.Tasks))
185		ids := make(map[string]struct{}, len(*req.Tasks))
186		for i := range *req.Tasks {
187			in := (*req.Tasks)[i]
188			if !validTaskID(in.ID) {
189				return nil, false
190			}
191			if _, dup := ids[in.ID]; dup {
192				return nil, false
193			}
194			ids[in.ID] = struct{}{}
195			if in.Priority == nil || *in.Priority < 0 || *in.Priority > 255 {
196				return nil, false
197			}
198			if in.Release == nil || *in.Release < 0 || *in.Release >= horizon {
199				return nil, false
200			}
201			if in.Execution == nil || *in.Execution <= 0 {
202				return nil, false
203			}
204			if in.Deadline == nil || *in.Deadline <= *in.Release {
205				return nil, false
206			}
207			tasks = append(tasks, scheduledTask{
208				id:        in.ID,
209				priority:  *in.Priority,
210				release:   *in.Release,
211				execution: *in.Execution,
212				deadline:  *in.Deadline,
213			})
214		}
215		return tasks, true
216	}
